public class CustomNetworkClassLoader extends ClassLoader {
    private final String serverUrl;

    public CustomNetworkClassLoader(ClassLoader parent, String serverUrl) {
        super(parent);
        this.serverUrl = serverUrl;
    }

    @Override
    protected Class<?> loadClass(String name, boolean resolve) throws ClassNotFoundException {
        synchronized (getClassLoadingLock(name)) {
            // 1. Check if the class has already been loaded
            Class<?> c = findLoadedClass(name);
            if (c == null) {
                try {
                    // 2. Delegate to parent first (Parent Delegation Model)
                    if (getParent() != null) {
                        c = getParent().loadClass(name, false);
                    } else {
                        c = findBootstrapClassOrNull(name);
                    }
                } catch (ClassNotFoundException e) {
                    // Parent squashed the request; proceed to local loading
                }

                if (c == null) {
                    // 3. Fallback to local custom loading mechanism
                    byte[] classData = fetchClassDataFromServer(name);
                    if (classData == null) {
                        throw new ClassNotFoundException(name);
                    }
                    c = defineClass(name, classData, 0, classData.length);
                }
            }
            if (resolve) {
                resolveClass(c);
            }
            return c;
        }
    }

